import { createSlice } from '@reduxjs/toolkit';
const initialState = {
    checks: [],
    selectedCheck: null,
    filters: {},
    loading: false,
    error: null,
    pagination: {
        page: 1,
        pageSize: 10,
        total: 0,
        totalPages: 0,
    },
};
const checksSlice = createSlice({
    name: 'checks',
    initialState,
    reducers: {
        // Loading states
        setLoading: (state, action) => {
            state.loading = action.payload;
            if (action.payload) {
                state.error = null;
            }
        },
        setError: (state, action) => {
            state.error = action.payload;
            state.loading = false;
        },
        clearError: (state) => {
            state.error = null;
        },
        // Checks management
        setChecks: (state, action) => {
            state.checks = action.payload;
            state.loading = false;
            state.error = null;
        },
        addCheck: (state, action) => {
            state.checks.unshift(action.payload);
            state.pagination.total += 1;
        },
        updateCheck: (state, action) => {
            const index = state.checks.findIndex(check => check.id === action.payload.id);
            if (index !== -1) {
                state.checks[index] = action.payload;
            }
            if (state.selectedCheck?.id === action.payload.id) {
                state.selectedCheck = action.payload;
            }
        },
        removeCheck: (state, action) => {
            state.checks = state.checks.filter(check => check.id !== action.payload);
            state.pagination.total -= 1;
            if (state.selectedCheck?.id === action.payload) {
                state.selectedCheck = null;
            }
        },
        updateCheckStatus: (state, action) => {
            const { id, status, lastExecuted } = action.payload;
            const check = state.checks.find(check => check.id === id);
            if (check) {
                check.lastStatus = status;
                if (lastExecuted) {
                    check.lastExecuted = lastExecuted;
                }
            }
            if (state.selectedCheck?.id === id) {
                state.selectedCheck.lastStatus = status;
                if (lastExecuted && state.selectedCheck) {
                    state.selectedCheck.lastExecuted = lastExecuted;
                }
            }
        },
        // Selection
        setSelectedCheck: (state, action) => {
            state.selectedCheck = action.payload;
        },
        // Filters
        setFilters: (state, action) => {
            state.filters = action.payload;
        },
        updateFilters: (state, action) => {
            state.filters = { ...state.filters, ...action.payload };
        },
        clearFilters: (state) => {
            state.filters = {};
        },
        // Pagination
        setPagination: (state, action) => {
            state.pagination = { ...state.pagination, ...action.payload };
        },
        // Reset state
        resetChecksState: () => initialState,
    },
});
export const { setLoading, setError, clearError, setChecks, addCheck, updateCheck, removeCheck, updateCheckStatus, setSelectedCheck, setFilters, updateFilters, clearFilters, setPagination, resetChecksState, } = checksSlice.actions;
export default checksSlice.reducer;
